PSEC["استيعاب المقروء"]=[
 _v("يشعر كثير من الناس بالعدوانية والسبب في هذه المشاعر السيئة هو الاستغراق في مستنقع مخيف وهو المقارنة، والإشكالية في هذا أن هؤلاء قد غاب عنهم أنهم نسيج وحدهم وغاب عنهم أنهم ليسوا مطالبين بأن يكونوا مثل فلان وفلان. قد خلق الله كل إنسان بصفة تميز ولمسة تفرد، إن النجاح الحقيقي لا يكون بمقارنة أوضاعك بالآخرين أو إنجازاتهم أو موقعك بموقعهم فهذا درب ينسف العطاءات ويقتل الطموحات. إن الرأي القاصر يكمن في الحكم على ذواتنا بمعايير عالمية ومقاييس جادة في حين تحكم على الآخرين بأفعالهم، ونجاحك الحقيقي يحدده التقارب بين إنجازاتك وقدراتك وباستغلال مواهبك واستثمار قدراتك، وإن كنت ولا بد مقارناً فقارن نفسك بنفسك أين كنت؟ وأين توقعت؟ فإن كنت من طلاب النجاح فلا خيار لديك غير بذل الجهد والاستعداد التام لدفع الثمن والصعود خطوة خطوة على قدميك.\n\nيُفهم من النص أن الإنسان ينبغي أن يكون:",["مستقلاً", "تابعاً", "ناجحاً", "متغيراً"],0,"النص يدعو ألا يقارن الإنسان نفسه بغيره وأن يكون له كيانه الخاص."),
 _v("(١) منذ بدء تسجيل الزلازل علمياً فإن أعتى الزلازل كانت على النحو التالي بمقياس ريختر: زلزال تشيلي عام (١٩٦٠) فقد سجل ٩,٥، وقتل ألفي شخص، وشرد ثلاثة آلاف آخرين، كما انتقلت هزاته إلى جزر هاواي، وقتلت ٦١ شخصاً، وإلى اليابان حيث قضت على ١٣٨ شخصاً. وزلزال الاسكا عام ١٩٦٤ الذي وصلت قوته إلى ٩,٢ درجات، ويعد أعنف زلزال شهده النصف الشمالي من الأرض، وتسبب بوفاة ١٢٥ شخصاً.\n(٢) وزلزال جزر أندريانوف عام ١٩٥٧ في الاسكا أيضاً وبلغت قوته ٩,١ درجات، وقد دمر جزيرة أدك بصورة كاملة، كما تسبب في تدمير حوض السفن في جزيرة إنماك المجاورة، وخطوط النفط الضخمة في منطقة ساندباي. وزلزال كمتشكا عام ١٩٥٢م الذي بلغت قوته تسع درجات وضرب منطقة كمتشكا على الحدود بين اليابان وروسيا وإن لم يسفر عن خسائر في الأرواح، واقتصرت أضراره على الماديات فقط. والزلزال الذي وقع قبالة سواحل سومطرة في نهاية ديسمبر عام ٢٠٠٤م وبلغت قوته ٨,٩ درجات، وقضى على أكثر من ٢٠٠ ألف شخص، إضافة إلى الخسائر المادية الجسيمة.\n\nيُفهم من الفقرتين (١) و (٢) أن عدد ضحايا الزلزال يرتبط:",["بنوع المكان", "بقوة الزلزال", "بتاريخ وقوعه", "بتعدد حدوثه"],0,"الأضرار اعتمدت على الأماكن التي وقعت فيها الزلازل، ولم تُذكر القوة على أنها السبب الرئيسي للدمار."),
 _v("يعد مرض السكري من الأمراض المنتشرة في هذا العصر، ومتى أهمل المريض علاجه والسيطرة عليه فقد يؤدي إلى مضاعفات خطيرة، بل ربما إلى الوفاة المبكرة، ويعد العامل الوراثي أحد أسباب هذا المرض، وقد يكون لأسباب أخرى. ولهذا المرض أعراض كثيرة منها الشعور بالعطش بشكل كبير بسبب زيادة معدل الجلوكوز في الجسم والذي يعمل على خروج المياه من أنسجة الجسم ويشعرك بجفاف الفم والحلق، مما يؤدي إلى تناول كميات كبيرة من الماء والسوائل؛ وبالتالي سيشعر المصاب بالسكري بالحاجة الدائمة إلى التبول. ومن الأعراض أيضاً الشعور بالتعب والدوار بشكل مستمر، فتصبح الرؤية لدى المريض ضبابية وغير واضحة ومشوشة، وكذلك الشعور بالصداع والإحساس بالقلق والتوتر؛ مما يؤدي إلى سرعة الغضب لأبسط الأمور. ومن أبرز تلك الأعراض البطء في اندمال الجروح والإصابات.\n\nتعد جملة «سيشعر المصاب بالسكري ...» في النص:",["نتيجة لما قبلها", "سبباً لما قبلها", "تأكيداً لما بعدها", "تمهيداً لما بعدها"],0,"العطش الكثير والسوائل الكثيرة نتيجتها الحاجة الدائمة إلى التبول."),
 _v("من سبل إدارة المراعي على نحو مثمر إنشاء سدود ترابية وعقوم وحواجز من أجل توزيع مياه الأمطار والاستفادة من مياه الجريان السطحي على أراضي المراعي المجاورة والصالحة لنمو النباتات. وقد تصل أحياناً كمية المياه المستخدمة في غمر الأرض الرعوية بهذه الطريقة ما نسبته ٥ إلى ١٠ أمثال الهطول المطري، ويتوقف ذلك على كفاءة الطريقة المستخدمة؛ مما يساعد على عدم اعتماد الرعاة في تغذية حيواناتهم على الأعلاف المروية تقليدياً؛ ويعني بالتالي توفير كميات هائلة من مياه الآبار التي تستخدم في ري محاصيل الأعلاف.\n\nنستنبط من النص أن تقنية «غمر الأرض» تؤدي إلى زيادة:",["المياه المستفاد منها", "هطول الأمطار", "المياه الجوفية المستهلكة", "المياه السطحية الموفرة"],0,"الغمر يستفيد من مياه الأمطار والجريان السطحي، فتزيد كمية المياه المستفاد منها."),
 _v("يعتبر المطر الحمضي من أخطر مشكلات البيئة التي تواجهها، ويؤثر على قطاع كبير منها.\n\nيُفهم من الفقرة السابقة أن:",["البيئة تتأثر بالمطر الحمضي", "مشكلات البيئة تواجه عقبات", "المطر له مخاطر", "المطر جزء من مشكلات البيئة"],0,"المطر الحمضي يؤثر على قطاع كبير من البيئة، فالبيئة تتأثر به."),
 _v("القراءة الجهرية تعني تمييز الكلمات والإلمام بمعناها، ولكنها كذلك تعني التفسير الشفهي لأفكار الكاتب لأفراد آخرين، إذ إن الناس يقرؤون لتسلية الآخرين، وإيصال المعلومة إليهم وإقناعهم بفكرة ما.\n\nفي النص علاقة جملة (ولكنها كذلك تعني...) بما قبلها علاقة:",["استدراك", "تعليل", "استنتاج", "تفسير"],0,"«لكن» أداة استدراك."),
 _v("الزعفران يستخدم في الطب التقليدي كمنشط وطارد ومانع للأرياح. وفي اليابان يوضع الزعفران في كبسولات وتستخدم في المساعدة على النوم في حالات الأرق. وفي الأبحاث العلمية الحديثة يستعمل الزعفران للحماية من السرطان، وفي حالات فقدان الذاكرة، وفي أمراض القلب. والزعفران يحوي مادة برتقالية غامقة اللون تذوب في الماء هي الكاروتين، ولها تأثير مضاد للأكسدة ومضاد للأورام، والكاروتين جيد للمحافظة على منع أمراض القلب وزيادة المناعة. ودلت الأبحاث العلمية في المكسيك أن الزعفران يساعد خلايا المناعة على القضاء على الخلايا السرطانية.\n\nيُفهم من النص أن مادة الكاروتين تساعد على القضاء على:",["السرطان", "الكوليسترول", "الدهون", "الزيوت"],0,"الكاروتين مضاد للأورام ويساعد خلايا المناعة على القضاء على الخلايا السرطانية."),
 _v("لا تحاول أن تجعل ابنك شخصك الآخر، في حين أن شخصاً واحداً يكفي.\n\nالمعنى الذي تدعو إليه هذه المقولة هو:",["الاستقلالية", "التربية", "القدوة", "التبعية"],0,"المقولة ترفض أن يكون الابن نسخة من أبيه، فهي تدعو إلى استقلاليته."),
 _v("النجاح يكون للناس الذين يعملون بجرأة دائماً، والفشل للمترددين.\n\nتحدث النص عن صنفين من الناس: الجريء والمتردد. ما الكلمتان اللتان تصفان الصنفين على الترتيب؟",["الحماسة – الإحجام", "البداية – النهاية", "الطموح – النجاح", "الإقدام – الفجأة"],0,"الجريء يتصف بالحماسة، والمتردد يتصف بالإحجام."),
 _v("١. يُعدّ الجمل من الحيوانات الأليفة المنتشرة في الخليج العربي، وهو من أكثر الحيوانات قدرة على التكيّف مع بيئة الصحراء القاسية، لذلك يُعرف باسم «سفينة الصحراء». وقد وهبه الله رقبة طويلة تساعده على الأكل من الأرض وقضم أوراق الأشجار العالية، مما يجعله قادراً على العيش في الأماكن التي يقل فيها العشب والماء.\n٢. يتميّز الجمل بقوة تحمّله وصبره العجيب، فهو يتحمل الجوع والعطش لفترات طويلة دون أن يضعف، حتى لو خارت قواه وفقد شيئاً من وزنه يظل صابراً متحملاً، لا يجزع ولا ينهار، ولذلك كان خير رفيق للإنسان في الترحال والسفر عبر الصحارى الواسعة.\n٣. كان للعرب أنواع من الجمال الأصيلة، منها الجمال الكندرية التي تُستخدم للزينة والجمال في المناسبات، والجمال العادية التي تُستخدم للركوب والترحال وحمل الأمتعة. وقد كانت لهذه الأنواع مكانة خاصة عند العرب، إذ اعتمدوا عليها في حياتهم اليومية، فكانت رمزاً للقوة والصبر والعزّة.\n٤. ومع مرور الزمن، ظهرت أنواع وافدة من الجمال جاءت من خارج الجزيرة العربية، مثل الجمل الصومالي والجمل الباكستاني والجمل الإثيوبي، وغيرها من الأنواع التي انتقلت إلى البلاد العربية واستُخدمت لأغراض مختلفة.\n٥. ومن الناحية العلمية، يوجد نوعان فقط من الجمال في العالم، هما: الجمل العربي ذو السنام الواحد الذي يعيش في المناطق الحارة كجزيرة العرب، والجمل البكتيري (أو البيكتيري) ذو السنامين الذي يعيش في المناطق الباردة. وهذان النوعان هما الأصل في جميع الجمال المنتشرة حول العالم.\n٦. لقد كان الجمل على مرّ العصور رمزاً للصبر والتحمّل، وقد سخّره الله لخدمة الإنسان، فاستفاد منه في طعامه وشرابه وسفره، حتى صار الجمل عنواناً على القوة والثبات والتكيّف مع الطبيعة القاسية.\n\nأي الآتي ذُكر في النص وهو مخالف لسياق النص؟",["يفقد قواه", "يخسر بعض من وزنه", "قضم الأوراق", "سلالات وافدة"],0,"النص يؤكد أن الجمل يتحمل الجوع والعطش دون أن يضعف، فذكر فقدانه لقواه يخالف السياق."),
 _v("تتراوح درجة حرارة الجمل بين ٣٤ و ٤١ درجة، وهذا يدل على:",["تحمل الجمل لدرجات الحرارة العالية", "قدرة تأقلم الجمل مع أي بيئة", "تحكمه في درجة حرارته", "قدرته على العيش في مناطق جغرافية متباينة"],0,"المدى الحراري الواسع يدل على قدرة الجمل على تحمل العيش في المناطق الحارة."),
 _v("أنا أمثل دور الأعمى عندما أرى زلة شخص لا أود خسارته.\n\nماذا يعني دور الأعمى في العبارة؟",["التجاهل", "التركيز", "الاحتقار", "التذاكي"],0,"من يمثل دور الأعمى يتغافل عن الزلة ولا يلتفت إليها، أي يتجاهلها."),
 _v("من الممكن استخراج الوقود البيولوجي ليحل محل الوقود من الطحالب، ولكن مازالت التجارب في بدايتها.\n\nالعبارة (ولكن مازالت التجارب في بدايتها) تدل على:",["احتمالية النجاح", "التأكد من النجاح", "الأسباب والنتائج", "تعليل للنجاح"],0,"التجارب في بدايتها، فالنجاح محتمل وليس مؤكداً."),
 _v("البيئة الملائمة هي التي تحول حلاً عادياً إلى حل ممتاز، ومن هنا فإن تكوين بيئات عمل ممتازة يظل هو الشيء الأكثر أهمية والأعظم نفعاً.\n\nنفهم من العبارة أن البيئة الملائمة تنتج لنا حلاً:",["فذاً", "ملائماً", "عادياً", "مادياً"],0,"البيئة الملائمة تحول الحل العادي إلى حل ممتاز، أي فذ."),
 _v("ما من شيء أثقل على الإنسان من الوقت الذي يقضيه بدون فعل شيء.\n\nتدل العبارة السابقة على أن الإنسان إذا جلس بمفرده فإنه:",["يتململ من الفراغ", "يهنأ", "يندم", "يبكي"],0,"الوقت دون عمل ثقيل على الإنسان، فيضيق ويتململ."),
 _v("ظلت كسوة الكعبة المشرفة تُرسل من مصر عبر القرون، إلى أن توقف إرسالها نهائياً من مصر عام ١٩٦٢م، ثم تولت المملكة العربية السعودية شرف صناعتها، فأنشأت مصنعاً مخصصاً لعمل الكسوة، افتتح عام ١٩٧٧م بأم الجود في مكة المكرمة.\n\nبدأت السعودية بتولي صناعة كسوة الكعبة في:",["أوائل الستينيات الميلادية", "أوائل السبعينيات", "نهاية الستينيات", "أواخر السبعينيات"],0,"توقف إرسالها من مصر عام ١٩٦٢م وبعدها تولت السعودية صناعتها."),
 _v("الماء أساس الحياة، فلا تخلو منه خلية حية. ومع ذلك يهدر الإنسان كميات كبيرة منه في الاستخدامات اليومية، مما يهدد بنقصه في المستقبل.\n\nالفكرة الرئيسة للنص:",["أهمية الماء وضرورة عدم الإسراف فيه", "كثرة الماء على الأرض", "اختلاف استخدامات الماء", "تلوث الماء"],0,"النص يبين أهمية الماء ويحذر من هدره."),
 _v("تعد القراءة من أهم وسائل اكتساب المعرفة، وكلما تنوعت القراءات اتسعت آفاق القارئ وتعددت زوايا نظره إلى الأمور.\n\nيفهم من النص أن تنوع القراءات:",["يوسع آفاق القارئ", "يقلل وقت القراءة", "يضعف التركيز", "يغني عن المعرفة"],0,"النص يصرح بأن تنوع القراءات يوسع آفاق القارئ."),
 _v("بدأت المدن تعتمد على الطاقة الشمسية في الإنارة لخفض تكاليف الكهرباء، لكن ارتفاع كلفة التركيب لا يزال عائقاً أمام انتشارها السريع.\n\nتدل عبارة (لكن ارتفاع كلفة التركيب لا يزال عائقاً) على:",["وجود عقبة تبطئ الانتشار", "تأكيد نجاح الفكرة", "سبب لخفض التكاليف", "نتيجة لانتشارها"],0,"(لكن) أداة استدراك، وما بعدها عائق أمام الانتشار."),
 _v("النوم الكافي ليس ترفاً، فهو يعيد للجسم نشاطه ويحسن قدرة الدماغ على التركيز، ولذلك يعاني من يسهر كثيراً من ضعف الانتباه.\n\nيفهم من النص أن النوم الكافي:",["ضروري لنشاط الجسم وتركيز الدماغ", "ترف لا حاجة إليه", "يضعف الانتباه", "يغني عن الراحة"],0,"النص ينفي أن النوم ترف ويبين أثره في النشاط والتركيز."),
];
