const LES={};
LES["التناظر اللفظي"]="حدّد العلاقة بين الكلمتين (ترادف، تضاد، جزء من كل، يقوم بـ، يحدث له، ينتج عنه...) ثم اختر الزوج الذي له العلاقة نفسها وبالترتيب نفسه.\nانتبه: عكس الترتيب يجعل الخيار خاطئاً حتى لو كانت العلاقة موجودة.";
LES["إكمال الجمل"]="اقرأ الجملة كاملة وحدّد المعنى العام، ثم جرّب كل خيار وانتبه لانسجام الكلمتين معاً مع السياق.\nاستبعد الخيارات التي تخل بالمعنى أو تتعارض مع بقية الجملة.";
LES["الخطأ السياقي"]="ابحث عن الكلمة التي تخالف معنى الجملة العام (ضد المقصود أو لا تناسب السياق)، ثم تحقق بأن استبدالها بضدها أو بما يناسب يصحح المعنى.";
LES["استيعاب المقروء"]="اقرأ السؤال أولاً ثم النص، وارجع للنص وابحث عن الإجابة فيه ولا تعتمد على معلوماتك السابقة.\nالإجابة الصحيحة هي ما يدل عليه النص صراحة أو يُستنتج منه مباشرة.";
LES["المفردات والمعاني"]="اربط الكلمة بسياقها، وابحث عن الخيار الأقرب في المعنى (أو الأبعد في أسئلة الاستثناء) بعد تجربة كل خيار.";
LES["الارتباط والاختلاف"]="حدّد العلاقة التي تجمع ثلاث كلمات من الأربع (ترادف، فئة واحدة، مجال واحد...) ثم اختر الكلمة التي تخرج عن هذه العلاقة.\nتأكد أن الكلمات الثلاث تشترك في الصفة نفسها قبل أن تحكم.";
